import { Navbar, NavbarAction, NavbarLink, NavbarLogo, NavbarMenuGroup, NavbarMenuLink } from '@syntara/react';

export function SiteNav() {
  return (
    <Navbar
      logo={<NavbarLogo href="/">Acme</NavbarLogo>}
      actions={
        <>
          <NavbarLink href="/login">Log in</NavbarLink>
          <NavbarAction href="/join">Join now</NavbarAction>
        </>
      }
      menu={
        <NavbarMenuGroup title="Explore">
          <NavbarMenuLink href="/plans">Plans</NavbarMenuLink>
          <NavbarMenuLink href="/clinics">Clinics</NavbarMenuLink>
        </NavbarMenuGroup>
      }
    >
      <NavbarLink href="/plans" isCurrent>Plans</NavbarLink>
      <NavbarLink href="/clinics">Clinics</NavbarLink>
    </Navbar>
  );
}
